  uint32_t time;
  /// `mPhysicalModel.GetFrame()`
  uint32_t frame;
  uint32_t hold_time;
  uint32_t start_frame;
  uint32_t last_frame;
  uint32_t frame_count;
  uint32_t frame_time;
